import React, { Component } from 'react'
import Form from 'react-bootstrap/Form'
import DataTable from 'react-data-table-component'
import moment from 'moment'

class MyMessagesTable extends Component {


    handleChange = (event) => {
      
          this.props.handleMyMessagesSelectedRowsChange(event.selectedRows);
    }
    
    
    render() {
        
        const showMyMessagesTable = this.props.showMyMessagesTable ? {display: 'block'} : {display: 'none'};

        const columns =  [
            { name: 'Recipient', selector: 'profileName', sortable: true },
            { name: 'Messaged', selector: 'createdAt', sortable: true, format: row => moment(row.timestamp).format("DD/MM/YYYY HH:MM:SS") },
            { name: 'Message', selector: 'message', sortable: true, wrap: true }
            ];
               
        return (
          
          <Form className="messagesDataTable">
              <DataTable style={showMyMessagesTable}
                columns={columns}
                data={this.props.myMessageData}
                defaultSortField="profileName"
                selectableRows
                onSelectedRowsChange={this.handleChange}
                highlightOnHover
                clearSelectedRows={this.props.toggledClearRows}
                pagination
                paginationPerPage={10}
              />
                       
          </Form>
        )
    }

}

export default MyMessagesTable;
